-- Plain-language spell descriptions (2026-10-12). Idempotent.
BEGIN;
UPDATE spells SET base_description = $d$You command a flame you can see to dance, flare up, or gutter out. You can also make the fire lash out and burn a creature near it.$d$ WHERE id = 1;
